import { coachContext } from './coach-continuity.mjs?v=20261101-tournaments';
export function buildAdviceRequest(caseData, profile, checkin, outcomeReview = false, stats = {}, recentChat = [], state = {}) {
  const c = caseData || {}, p = profile || {};
  const brief = value => typeof value === 'string' ? value.trim().slice(0, 350) : '';
  const context = coachContext({ ...state, profile: p, stats, aiMessages: recentChat }, c, checkin);
  const message = [
    outcomeReview
      ? 'Оцени результат проверки игрока по его тексту. Ты не видишь файл или статистику. Ответь по-русски, предметно: (1) выполнено ли выбранное действие по предоставленным данным; (2) что результат доказывает и чего ещё не доказывает; (3) одно следующее упражнение или изменение с условием и метрикой под режим и роль. Если игрок написал только «нет» или фактов мало, скажи, что нельзя оценить игру, и попроси одну конкретную деталь. Не больше 180 слов.'
      : 'Разбери ОДИН эпизод по описанию игрока. Ты не видишь клип, скрин, реплей или трекер. Ответь по-русски, предметно и без шаблонной похвалы. Проверь цепочку: что игрок знал → что решил → что произошло. Отдели наблюдение от предполагаемой причины; назови первое звено, где была доступная альтернатива. Затем дай ОДНО конкретное игровое упражнение под роль и режим: когда его применять, сколько подходящих ситуаций собрать и какой результат записать. Учитывай сегодняшнее время и состояние. При малом запасе сил предложи безопасную работу с повтором вместо обязательной игры. Если фактов мало, попроси одну точную деталь, не выдумывай диагноз. Не больше 180 слов.',
    `Описание: ${brief(c.note)}`,
    ...(Array.isArray(c.answers) ? c.answers.slice(0, 3).map((answer, i) => `Ответ ${i + 1}: ${brief(answer).slice(0, 220)}`) : []),
    ...(c.action ? [`Что игрок решил проверить: ${brief(c.action).slice(0, 180)}`] : []),
    ...(c.outcome ? [`Результат по словам игрока: ${brief(c.outcome).slice(0, 180)}`] : [])
  ].join('\n').slice(0, 1800);
  return { context, messages: [{ role: 'user', content: message }] };
}
